// 4M2 area is covered surface, separate from all perimeter and fraction renderers.
function areaMeasure4(v){return Math.abs(v.reduce((s,a,i)=>{const b=v[(i+1)%v.length];return s+a[0]*b[1]-b[0]*a[1];},0))/2;}
function areaInside4(x,y,v){let inside=false;for(let i=0,j=v.length-1;i<v.length;j=i++){const a=v[i],b=v[j];if((a[1]>y)!==(b[1]>y)&&x<(b[0]-a[0])*(y-a[1])/(b[1]-a[1])+a[0])inside=!inside;}return inside;}
